(function(){
 'use strict';
 const a=window.VersionCompassAdvisor,esc=a.esc,parsed=a.read(location.search);let state=parsed.state;
 const main=document.querySelector('main'),key='versioncompass-advisor-profile-v1';
 document.documentElement.classList.add('perspective-enabled');document.body.classList.add('editions-preview','advisor-view');document.title='Version Compass | Advisor · Work in progress';document.querySelector('.skip-link').href='#advisor-context';document.querySelector('.agent-note')?.setAttribute('hidden','');
 const options=(rows,value)=>Object.entries(rows).map(([v,label])=>'<option value="'+esc(v)+'"'+(v===value?' selected':'')+'>'+esc(label)+'</option>').join('');
 const select=(label,id,rows,goals='')=>'<label'+(goals?' data-goals="'+goals+'"':'')+'>'+esc(label)+'<select id="advisor-'+id+'">'+options(rows,state[id])+'</select></label>';
 const input=(label,id,goals)=>'<label data-goals="'+goals+'">'+esc(label)+'<input id="advisor-'+id+'" maxlength="40" inputmode="decimal" placeholder="Unknown · e.g. 5.0.0" autocomplete="off"></label>';
 const capabilityGoals='agent-mode itsi-assistant soc-workflow';
 main.innerHTML='<section class="hero ai-hero advisor-hero"><div class="eyebrow">SPLUNK DOCUMENTATION / YOUR GOAL</div><h1 id="advisor-title">Advisor. <span>A reason for the next step.</span></h1><p class="dek">Start with what you want to do. Compare your reported context with assessed Splunk documentation, and see the prerequisites, gaps and contradictions behind each path.</p><p class="ai-hero-note">Work in progress · A focused first set of goals · Unknown is a valid answer</p><div class="report-actions"><button id="copy-link" type="button">Copy goal link</button><button id="print-report" type="button">Print / save PDF</button><span id="share-status" role="status"></span></div></section><div class="ai-body advisor-body"><aside id="advisor-warning" class="ai-warning" role="alert" hidden></aside><div id="advisor-content"><section id="advisor-context" class="ai-section"><p class="kicker">01 / YOUR GOAL AND CONTEXT</p><h2>What are you trying to achieve?</h2><p>Your inputs are self-reported. Leave anything you cannot confirm unknown.</p><div class="ai-controls advisor-controls">'+select('Goal','goal',a.goals)+select('Deployment','deployment',a.choices.deployment,capabilityGoals)+select('Service environment','compliance',a.choices.compliance,capabilityGoals)+select('AI service region','region',{unknown:'Unknown',...Object.fromEntries(window.VersionCompassAIAvailability.regions().map(r=>[r.id,r.label+' · '+r.provider]))},capabilityGoals)+select('ES edition','edition',a.choices.edition,'soc-workflow')+select('Capability access and enablement','access',a.choices.access,capabilityGoals)+input('Installed Platform version','platformVersion','agent-mode')+input('Installed ITSI version','itsiVersion','itsi-versions itsi-assistant')+input('Installed SAIA version','saiaVersion','itsi-versions itsi-assistant')+input('Installed Splunk MCP Server version','mcpVersion','itsi-versions itsi-assistant')+'</div><p class="ai-note">A reported confirmation is not evidence of entitlement or authorization. An AI service region is distinct from where your Platform runs. Version comparisons establish only the cited floors.</p><div class="advisor-profile-actions" role="group" aria-label="Local profile"><button id="advisor-save" type="button">Save profile on this device</button><button id="advisor-load" type="button">Load saved profile</button><button id="advisor-clear" type="button">Clear profile</button></div><p id="advisor-profile-status" class="ai-note" role="status">This profile stays in this browser. Goal links exclude your context; downloaded reports include it.</p></section><section id="advisor-results" class="ai-section" aria-labelledby="advisor-result-heading"><p class="kicker">02 / EVIDENCE BEFORE ACTION</p><h2 id="advisor-result-heading" class="sr-only">Your guidance</h2><div id="advisor-result" aria-live="polite" aria-atomic="true"></div></section><section id="advisor-sources" class="ai-section"><p class="kicker">03 / ASSESSED PUBLIC DOCUMENTATION</p><h2>Sources for this goal</h2><div id="advisor-source-list"></div><p class="ai-note">Claim admission is specific to this goal. Being hosted by Splunk does not automatically admit a source or settle contradictions. Existing source and claim dates are preserved.</p></section><section id="advisor-scope" class="ai-section"><p class="kicker">04 / CURRENT SCOPE</p><h2>A focused start, with room to grow</h2><p>Advisor uses deterministic rules and our assessed published Splunk documentation. It does not discover your environment or use a runtime model.</p><p>Licensing, sizing and operational advice for which we do not maintain sufficient assessed evidence are outside this build. They remain future potential. No inference of entitlement, health, compliance or customer authorization is made.</p><p><a href="/">Open the Release Guide</a> · <a href="/?view=ai-availability">Explore AI Availability</a></p></section></div></div>'+a.report(state);
 const get=id=>document.getElementById('advisor-'+id);
 function goalURL(){const p=new URLSearchParams({view:'advisor'});if(state.goal!=='unknown')p.set('goal',state.goal);if(new URLSearchParams(location.search).get('theme')==='cisco')p.set('theme','cisco');return '/?'+p;}
 function render(){if(parsed.errors.length)return;state=a.normalize(state);for(const k of Object.keys(a.defaults)){if(get(k))get(k).value=state[k];}document.querySelectorAll('[data-goals]').forEach(el=>{el.hidden=!el.dataset.goals.split(' ').includes(state.goal);});
  const result=a.evaluate(state);get('result').innerHTML=a.resultHTML(result);get('source-list').innerHTML=result.sources.length?a.sources(result):'<p>No factual capability path is offered for this selection. Choose an assessed goal to view its supporting documentation.</p>';document.querySelector('main>.advisor-report').outerHTML=a.report(state);}
 for(const k of Object.keys(a.defaults)){get(k)?.addEventListener(k.endsWith('Version')?'input':'change',e=>{state[k]=e.target.value;if(k==='goal')history.pushState(null,'',goalURL());render();});}
 get('save').addEventListener('click',()=>{try{localStorage.setItem(key,JSON.stringify({schemaVersion:1,profile:state}));get('profile-status').textContent='Profile saved in this browser only.';}catch{get('profile-status').textContent='This browser could not save a profile. You can continue without saving.';}});
 get('load').addEventListener('click',()=>{try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.schemaVersion!==1||!saved.profile)throw Error();state=a.normalize(saved.profile);history.pushState(null,'',goalURL());render();get('profile-status').textContent='Saved self-reported profile loaded. Confirm it is still accurate.';}catch{get('profile-status').textContent='No usable saved profile is available in this browser.';}});
 get('clear').addEventListener('click',()=>{try{localStorage.removeItem(key);}catch{}state=a.normalize();history.pushState(null,'',goalURL());render();get('profile-status').textContent='Profile cleared. All context is unknown.';});
 window.addEventListener('popstate',()=>{const next=a.read(location.search);if(next.errors.length){location.reload();return;}state.goal=next.state.goal;render();});
 document.getElementById('copy-link').addEventListener('click',async()=>{const url=new URL(goalURL(),location.origin).href;try{await navigator.clipboard.writeText(url);document.getElementById('share-status').textContent='Goal link copied. Your context is excluded.';}catch{document.getElementById('share-status').textContent='Goal link: '+url;}});
 document.getElementById('print-report').addEventListener('click',()=>window.print());
 window.VersionCompassBuildSnapshot=()=>{if(parsed.errors.length)throw Error('Correct the Advisor link before exporting.');return a.report(state);};
 if(parsed.errors.length){get('warning').hidden=false;get('warning').innerHTML='<h2>This Advisor link needs correction</h2><ul>'+parsed.errors.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><a href="/?view=advisor">Open a fresh Advisor view</a>';get('content').hidden=true;for(const id of ['copy-link','print-report'])document.getElementById(id).disabled=true;document.querySelector('main>.advisor-report').remove();}else render();
}());
